parameters.functionCode:
const dbResult = $('GuardarEnNeonDB').item.json;
const data = $('NormalizarDatos').item.json;
const calendarEvent = $('CrearEventoCalendar').item.json;

const reservationId = `RES-${data.fecha.replace(/-/g, '')}-${String(dbResult.id).padStart(3, '0')}`;

return [{
  json: {
    reservationId,
    nombre: data.nombre,
    email: data.email,
    telefono: data.telefono,
    fecha: data.fechaFormateada,
    hora: data.horaFormateada,
    pax: data.pax,
    tipoEvento: data.tipoEvento,
    extras: data.extras,
    metodoPago: data.metodoPago,
    total: data.precioTotal,
    deposito: data.depositoAmount,
    calendarEventId: calendarEvent.id || '',
    dbId: dbResult.id
  }
}];

